 private static boolean validEcologyTarget(WorldState s,String from,String target){if(target==null||target.isEmpty())return true;if(s==null||s.world==null)return false;WorldArea a=s.world.area(from),b=s.world.area(target);return a!=null&&b!=null&&a.connections.contains(target);}
