 private static void normalizeTravel(TravelState t,String actor){if(t==null)return;t.actor=actor;t.progress=Math.max(0,Math.min(1,t.progress));t.interactionRange=Math.max(0,t.interactionRange);t.distanceTravelled=Math.max(0,t.distanceTravelled);if(!t.active)return;boolean local="LOCAL".equals(t.travelMode),valid=local?Float.isFinite(t.segmentEndX):t.route.size()>1&&t.routeIndex>=0&&t.routeIndex<t.route.size()-1&&Float.isFinite(t.segmentEndX);if(!valid){t.active=false;t.interruption="invalid runtime travel state";t.lastSpeed=0;t.lastDelta=0;}}
 private static <T> void trimOldest(java.util.List<T> list,int max){if(list==null)return;while(list.size()>max)list.remove(0);}
 public static boolean valid(WorldState s){if(s==null||s.world==null||s.catState==null||s.catTravel==null||s.catSearch==null)return false;boolean attached="girl".equals(s.catState.attachedToEntity);WorldArea ca=s.world.areaAt(s.catState.x),ga=s.world.areaAt(s.haruX);if(attached&&(ca==null||ga==null||!ca.id.equals(ga.id)))return false;if(attached&&s.catTravel.active)return false;if(attached&&!s.catState.carryKnownByGirl)return false;if("APPROACHING_GIRL".equals(s.catState.sleepMode)&&attached)return false;if("HOME".equals(s.catState.sleepMode)&&attached)return false;if("RESTING_WHERE_STRANDED".equals(s.catState.sleepMode)&&s.catTravel.active)return false;if(!s.catState.awake&&"RESTING_WHERE_STRANDED".equals(s.catState.sleepMode)&&s.catState.actualSleepStartedAt<=0)return false;return true;}
